# Decode binary frames to ASCII timestamps with 12 decimal places.
#
# Frame: [4 bytes PICstop_low32][4 bytes tof][1 byte chID][0x0D][0x0A] = 11 bytes
#
# Rollover handling:
# - Track 32-bit PICstop per channel.
# - When current low32 < previous low32 by at least min_wrap_delta, increment rollover.
# - Effective 64-bit PICstop = (rollover << 32) | low32.

import argparse
import os
import sys
from typing import Iterable, List, Optional, Tuple, Dict

FRAME_LEN = 11
CR = 0x0D
LF = 0x0A

# Default: 100,000,000 picoseconds per tick (100 microseconds)
PS_PER_TICK_DEFAULT = 100_000_000  # picoseconds

UINT32_MAX = 0xFFFFFFFF
TWO32 = 1 << 32


def parse_args():
    p = argparse.ArgumentParser(
        description="Decode captured binary frames to ASCII timestamps with rollover handling."
    )
    p.add_argument("--infile", required=True, help="Path to captured binary file")
    p.add_argument(
        "--outfile",
        required=True,
        help="Output file (for interleaved) or prefix (for per-channel)",
    )
    p.add_argument(
        "--channels",
        nargs="+",
        help="Expected channel IDs (one or two). Example: A or A B. If omitted, accept any alphanumeric.",
    )
    p.add_argument(
        "--strict-channels",
        action="store_true",
        help="If set, drop frames with channel IDs not in --channels.",
    )
    p.add_argument(
        "--interleave",
        action="store_true",
        help="If set, write a single interleaved output file sorted by timestamp.",
    )
    p.add_argument(
        "--endianness",
        choices=["little", "big"],
        default="little",
        help="Endianness of PICstop/tof fields.",
    )
    p.add_argument(
        "--ps-per-tick",
        type=int,
        default=PS_PER_TICK_DEFAULT,
        help="PS_PER_TICK constant (picoseconds per tick). Default 100,000,000",
    )
    p.add_argument(
        "--max-errors",
        type=int,
        default=1000,
        help="Maximum parse errors before aborting.",
    )
    p.add_argument(
        "--keep-bad",
        action="store_true",
        help="If set, write bad/misaligned bytes to a sidecar .bad file for diagnosis.",
    )
    p.add_argument(
        "--min-wrap-delta",
        type=int,
        default=1_000,  # ticks; guard against tiny out-of-order glitches
        help="Minimum drop in low32 to consider as a rollover event. Default 1000.",
    )
    p.add_argument(
        "--seed-rollover",
        nargs="+",
        help="Seed rollover count per channel like A:3 B:0. Useful for multi-part files.",
    )
    return p.parse_args()


def parse_seed_rollover(seed_list: Optional[List[str]]) -> Dict[str, int]:
    seeds: Dict[str, int] = {}
    if not seed_list:
        return seeds
    for item in seed_list:
        try:
            ch, val = item.split(":", 1)
            ch = ch.strip()
            val_i = int(val.strip())
            if len(ch) == 1 and ch.isalnum() and val_i >= 0:
                seeds[ch] = val_i
        except Exception:
            pass
    return seeds


def find_frames(data: bytes):
    """
    Yield (offset, frame) tuples for every 11-byte frame ending with CRLF.
    If misaligned, scan for CRLF and step back 10 bytes to get the frame start.
    """
    i = 0
    n = len(data)
    while i + FRAME_LEN <= n:
        frame = data[i : i + FRAME_LEN]
        if frame[-2] == CR and frame[-1] == LF:
            yield (i, frame)
            i += FRAME_LEN
        else:
            j = data.find(bytes([CR, LF]), i + 1)
            if j == -1:
                break
            start = j - (FRAME_LEN - 2)
            if start >= 0 and start + FRAME_LEN <= n:
                frame = data[start : start + FRAME_LEN]
                if frame[-2] == CR and frame[-1] == LF:
                    yield (start, frame)
                    i = start + FRAME_LEN
                    continue
            i = j + 2


def parse_frame(frame: bytes, endianness: str) -> Tuple[int, int, str]:
    order = "little" if endianness == "little" else "big"
    picstop_low = int.from_bytes(frame[0:4], order, signed=False)
    tof = int.from_bytes(frame[4:8], order, signed=False)
    ch = chr(frame[8])
    return picstop_low, tof, ch


def valid_channel(ch: str) -> bool:
    return ch.isalnum()


def compute_timestamp_seconds(picstop_full: int, tof: int, ps_per_tick: int) -> float:
    # timestamp = ((PICstop * PS_PER_TICK) - tof) / 1e12
    numerator_ps = (picstop_full * ps_per_tick) - tof
    return numerator_ps / 1e12


def load_file(path: str) -> bytes:
    with open(path, "rb") as f:
        return f.read()


def main():
    args = parse_args()

    data = load_file(args.infile)
    errors = 0

    per_channel_rows: Dict[str, List[Tuple[float, str]]] = {}
    interleaved_rows: List[Tuple[float, str]] = []

    bad_bytes: bytearray = bytearray()

    # Rollover tracking per channel
    last_low32: Dict[str, Optional[int]] = {}
    rollover_count: Dict[str, int] = parse_seed_rollover(args.seed_rollover)

    for offset, frame in find_frames(data):
        try:
            picstop_low, tof, ch = parse_frame(frame, endianness=args.endianness)
        except Exception:
            errors += 1
            if args.keep_bad:
                bad_bytes.extend(frame)
            if errors > args.max_errors:
                print(
                    f"Too many parse errors (> {args.max_errors}). Aborting.",
                    file=sys.stderr,
                )
                break
            continue

        # Channel filtering
        if args.channels:
            if ch not in args.channels:
                if args.strict_channels:
                    continue
                else:
                    if not valid_channel(ch):
                        continue
        else:
            if not valid_channel(ch):
                continue

        # Initialize per-channel tracking
        if ch not in last_low32:
            last_low32[ch] = None
        if ch not in rollover_count:
            rollover_count[ch] = 0

        # Rollover detection
        prev = last_low32[ch]
        if prev is not None:
            if picstop_low < prev and (prev - picstop_low) >= args.min_wrap_delta:
                rollover_count[ch] += 1
        last_low32[ch] = picstop_low

        picstop_full = (rollover_count[ch] << 32) | picstop_low

        ts = compute_timestamp_seconds(picstop_full, tof, args.ps_per_tick)

        # Output line: "timestamp ch"
        line = f"{ts:.12f} {ch}\n"

        if args.interleave:
            interleaved_rows.append((ts, line))
        else:
            per_channel_rows.setdefault(ch, []).append((ts, line))

    # Write outputs
    if args.interleave:
        interleaved_rows.sort(key=lambda x: x[0])
        with open(args.outfile, "w", encoding="utf-8", newline="\n") as f:
            for _, line in interleaved_rows:
                f.write(line)
    else:
        if not per_channel_rows:
            print(
                "No frames decoded for selected channels.",
                file=sys.stderr,
            )
        for ch, rows in per_channel_rows.items():
            rows.sort(key=lambda x: x[0])
            root, ext = os.path.splitext(args.outfile)
            if ext:
                path = f"{root}_{ch}{ext}"
            else:
                path = f"{args.outfile}_{ch}.txt"
            with open(path, "w", encoding="utf-8", newline="\n") as f:
                for _, line in rows:
                    f.write(line)

    if args.keep_bad and len(bad_bytes) > 0:
        bad_path = args.outfile + ".bad"
        with open(bad_path, "wb") as fb:
            fb.write(bad_bytes)
        print(
            f"Wrote {len(bad_bytes)} bytes of rejected frames to {bad_path}",
            file=sys.stderr,
        )


if __name__ == "__main__":
    main()

